













































































































































































fn push_relations(lines: &mut Lines, groups: &[RelationGroup], within: Option<&ProjectRef>) {
    if groups.is_empty() {
        return;
    }
    lines.blank();
    lines.push("## relations");
    for group in groups {
        lines.push(format!(
            "→ {} ({})",
            group.label().as_str(),
            group.relations().len()
        ));
        for relation in group.relations() {
            lines.push(format!(
                "  {}  `{}`",
                relation.identity().trail_within(within),
                relation.identity().coordinate()
            ));
        }
    }
}






































































































































































































